export const Integer = 'integer'
export const Int32 = 'int32'
export const Float = 'float'
export const BooleanT = 'boolean'
export const StringT = 'string'
export const Void = 'void'
export const Null = 'null'
export const Any = 'any'

export const ByteArrayClass = 'Uint8Array'    // Uint8Array is also used as byte[].
export const FixedArrayClass = 'FixedArray'

export type StaticType = 'integer' | 'int32' | 'float' | 'boolean' | 'string' | 'void' | 'null' | 'any' |
  ObjectType | FunctionType | UnionType | EnumType

export function isBuiltinTypeName(name: string) {
  return name === Integer || name === Int32 || name === Float || name === BooleanT || name === Void || name === StringT || name === Null ||
         name === Any || name === 'undefined' || name === 'Array' || name === 'object'
}

export function isPrimitiveType(type: StaticType) {
  // unless String, Null, FunctionType, Any, or object type
  return type === Integer || type === Int32 || type === Float || type === BooleanT || type === Void || (type instanceof EnumType)
}

export function isIntegerType(t: StaticType) {
  return t === Integer || t === Int32
}

export function isIntegerLike(t: StaticType) {
  return isIntegerType(t) || (t instanceof EnumType)
}

export function isNumeric(t: StaticType) {
  return t === Integer || t === Int32 || t === Float || (t instanceof EnumType)
}

export function isEnum(t: StaticType) {
  return t instanceof EnumType
}

export class EnumType {
  name: string
  members: Map<string, number>

  constructor(name: string) {
    this.name = name
    this.members = new Map<string, number>()
  }

  addMember(name: string, value: number) {
    if (this.members.has(name))
      return false
    else {
      this.members.set(name, value)
      return true
    }
  }

  getMember(name: string) {
    return this.members.get(name)
  }
}

// the common super class of ObjectType and FunctionType
abstract class CompositeType {
  abstract name(): string
  abstract isSubtypeOf(t: StaticType): boolean
  abstract sameType(t: StaticType): boolean

  sourceName() { return this.name() }
}

// A singleton class.
// This class and its subclasses represent value_t values.
export class ObjectType extends CompositeType {
  name() {
    return 'object'
  }

  isSubtypeOf(t: StaticType): boolean {
    return this === t || this.superType()?.isSubtypeOf(t) || false
  }

  sameType(t: StaticType): boolean {
    return this === t
  }

  superType(): ObjectType | null { return null }
}

export const objectType = new ObjectType()

// this is one of primitive types
export class FunctionType extends CompositeType {
  returnType: StaticType
  paramTypes: StaticType[]

  constructor(returnType: StaticType, paramTypes: StaticType[]) {
    super()
    this.returnType = returnType
    this.paramTypes = paramTypes
  }

  name() {
    return `(${this.paramTypes.map(typeToString)}) => ${typeToString(this.returnType)}`
  }

  isSubtypeOf(t: StaticType): boolean {
    if (t instanceof FunctionType)
      if (isSubtype(this.returnType, t.returnType)
        && this.paramTypes.length === t.paramTypes.length) {
        for (let i = 0; i < this.paramTypes.length; i++)
          if (!isSubtype(t.paramTypes[i], this.paramTypes[i]))
            return false
        return true
      }

    return false
  }

  sameType(t: StaticType): boolean {
    if (t instanceof FunctionType)
      if (sameType(this.returnType, t.returnType)
        && this.paramTypes.length === t.paramTypes.length) {
        for (let i = 0; i < this.paramTypes.length; i++)
          if (!sameType(t.paramTypes[i], this.paramTypes[i]))
            return false
        return true
      }

    return false
  }
}

// This class represents both an array of instances and an array of primitive types.
// It does not represent built-in array-like types such as Uint8Array and FixedArray.
export class ArrayType extends ObjectType {
  // see builtinPropertiesAndMethods in classes.ts
  static readonly lengthProperty = 'length'
  static readonly pushMethod = 'push'
  static readonly popMethod = 'pop'
  static readonly unshiftMethod = 'unshift'
  static readonly shiftMethod = 'shift'

  elementType: StaticType

  constructor(element: StaticType) {
    super()
    this.elementType = element
  }

  name() {
    const etype = typeToString(this.elementType)
    if (this.elementType instanceof FunctionType || this.elementType instanceof UnionType)
      return `(${etype})[]`
    else
      return `${etype}[]`
  }

  isSubtypeOf(t: StaticType): boolean {
    return this.sameType(t)
  }

  sameType(t: StaticType): boolean {
    if (t instanceof ArrayType)
      return sameType(this.elementType, t.elementType)

    return false
  }

  findMethod(name: string): [StaticType, number, this] | undefined {
    if (isPrimitiveType(this.elementType))
      return undefined  // primitive-type arrays do not have methods
    else if (name === ArrayType.pushMethod)
      return [new FunctionType(Integer, [this.elementType]), 0, this]
    else if (name === ArrayType.popMethod)
      return [new FunctionType(new UnionType([this.elementType, Null]), []), 1, this]
    else if (name === ArrayType.unshiftMethod)
      return [new FunctionType(Integer, [this.elementType]), 2, this]
    else if (name === ArrayType.shiftMethod)
      return [new FunctionType(new UnionType([this.elementType, Null]), []), 3, this]
    else
      return undefined
  }
}

// This class is used only for holding built-in method names.
// see builtinPropertiesAndMethods in classes.ts
export class StringType {
  static readonly lengthProperty = ArrayType.lengthProperty

  static readonly startsWithMethod = 'startsWith'
  static readonly startsWithType = new FunctionType(BooleanT, [StringT])

  static readonly endsWithMethod = 'endsWith'
  static readonly endsWithType = new FunctionType(BooleanT, [StringT])

  static readonly substringMethod = 'substring'
  static readonly substringType = new FunctionType(StringT, [Integer, Integer])

  static findMethod(name: string): [StaticType, number] | undefined {
    if (name === 'startsWith')
      return [this.startsWithType, 0]
    else if (name === 'endsWith')
      return [this.endsWithType, 1]
    else if (name === 'substring')
      return [this.substringType, 2]
    else
      return undefined
  }
}

export class UnionType extends CompositeType {
  types: StaticType[]

  constructor(types: StaticType[]) {
    super()
    this.types = types
  }

  name() {
    return this.types.map(t => typeToString(t)).join('|')
  }

  isSubtypeOf(t: StaticType): boolean {
    for (const sub of this.types)
      if (!isSubtype(sub, t))
        return false

    return true
  }

  isSuperTypeOf(t: StaticType): boolean {
    for (const sup of this.types)
      if (isSubtype(t, sup))
        return true

    return false
  }

  sameType(t: StaticType): boolean {
    if (t instanceof UnionType && t.types.length === this.types.length) {
      for (const e of t.types)
        if (!this.isOneOfTypes(e))
          return false

      return true
    }

    return false
  }

  private isOneOfTypes(t: StaticType) {
    for (const t2 of this.types)
      if (sameType(t, t2))
        return true

    return false
  }

  isNullable() {
    if (this.types.length !== 2)
      return undefined

    let index
    if (this.types[0] === Null)
      index = 1
    else if (this.types[1] === Null)
      index = 0
    else
      return undefined

    const t = this.types[index]
    if (t instanceof ObjectType || t === StringT)
      return t
    else
      return undefined
  }

  hasStringOrBoolean() {
    for (const t of this.types)
      if (t === StringT || t === BooleanT)
        return true

    return false
  }
}

// type name used for error messages
export function typeToString(type: StaticType): string {
  if (type instanceof CompositeType)
    return type.sourceName()
  else if (type === Null)
    return 'undefined'
  else if (type instanceof EnumType)
    return type.name
  else
    return type
}

// When this function is modified,
// get/set/acc_anyobj_property(), gc_dynamic_method_call(), and is_subtype_of()
// in c-runtime.c must be modified accordingly.
export function encodeType(type: StaticType): string {
  switch (type) {
  case Integer:
  case Int32:
    return 'i'
  case Float:
    return 'f'
  case BooleanT:
    return 'b'
  case StringT:
    return 's'
  case Void:
    return 'v'
  case Null:
    return 'n'
  case Any:
    return 'a'
  default:
    if (type instanceof ArrayType)
      return '[' + encodeType(type.elementType)
    else if (type instanceof FunctionType)
      return `(${type.paramTypes.map(e => encodeType(e)).join('')})${encodeType(type.returnType)}`
    else if (type instanceof ObjectType)
      return `'${type.name()}'`
    else if (type instanceof UnionType)
      return '|' + type.types.map(e => encodeType(e)).join('')
    else if (type instanceof EnumType)
      return 'i'  // enums are represented as integers
    else
      throw new Error(`cannot encode: ${typeToString(type)}`)
  }
}

// t1 is a subtype of t2 when a t1 value is assignable to a t2 variable without explicit conversion
// with respect to its implementation in the C language.  We here assume that coercion is implicit
// conversion.
export function isSubtype(subtype: StaticType, type: StaticType): boolean {
  if (type === subtype)
    return true     // subclassing has not been implemented yet.
  else if (subtype instanceof UnionType)
    return subtype.isSubtypeOf(type)
  else if (type instanceof UnionType)
    return type.isSuperTypeOf(subtype)
  else if (isIntegerType(subtype))
    return isIntegerType(type) || type === Float
  else if (subtype === StringT)
    return type === objectType
  else if (subtype === BooleanT)
    return type === BooleanT
  else if (subtype instanceof CompositeType)
    return subtype.isSubtypeOf(type)
  else if (subtype instanceof EnumType)
    return isIntegerType(type) || type === Float
  else
    return false
}

export function sameType(t1: StaticType, t2: StaticType) {
  if (t1 === t2)
    return true
  else if (t1 instanceof CompositeType)
    return t1.sameType(t2)
  else
    return false
}

// isConsistent(t1, t2) is true when a t1 value is assignable to a t2 variable
// after explicit conversion.  That conversion may throw a runtime type error.
export function isConsistent(t1: StaticType, t2: StaticType) {
  if (t1 === Any)
    return t2 !== Any && t2 !== Void && t2 !== Int32
  else if (t2 === Any)
    return (t1 !== Void && t1 !== Int32)
  else if (t1 instanceof ArrayType && t2 instanceof ArrayType)
    if (isConsistent(t1.elementType, t2.elementType))
      return true
    else
      return t1.elementType === Int32 && t2.elementType === Any
        || t1.elementType === Any && t2.elementType === Int32
  else
    return false
}

export function commonSuperType(t1: StaticType, t2: StaticType): StaticType | undefined {
  if ((t1 === Integer && t2 === Int32) || (t1 === Int32 && t2 === Integer))
    return Int32
  else if (isSubtype(t1, t2))
    return t2
  else if (isSubtype(t2, t1))
    return t1
  else if (t1 instanceof ObjectType) {
    const s = t1.superType()
    if (s !== null)
      return commonSuperType(s, t2)
  }

  return undefined
}
